insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('e77d8d39-b481-4f52-b7de-5aa2fd633e00', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$inleiding: bungeejump van 70 meter, lichaam in de stress-stand$$,
   $$biologie-havo-2019-i-bungeejumpen-context1.png$$,
   $$Je staat op een platform op een hoogte van 70 meter en laat je voorover de diepte in vallen (afbeelding 1). Hierbij gaat je lichaam over op de stress-stand.$$, 'inline'),
  ('dae9b3c7-9586-42c4-8900-97cf8b0b7a99', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$adrenaline bij stress; afbeelding 1 (bungeejump) en afbeelding 2 (klieren P t/m T)$$,
   $$biologie-havo-2019-i-bungeejumpen-context2.png$$,
   $$Bij het overschakelen van het lichaam naar de stress-stand wordt het hormoon adrenaline afgegeven.
afbeelding 1: foto van een bungeejumper onder een kraan
afbeelding 2: tekening van het menselijk lichaam met een aantal klieren, aangegeven met de letters P, Q, R, S en T$$, 'inline'),
  ('e4dc9a2f-3a4f-4184-a1f2-9f5841d46f9e', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$in afbeelding 2 zijn klieren met letters aangegeven$$,
   $$biologie-havo-2019-i-bungeejumpen-context3.png$$,
   $$In afbeelding 2 is een aantal klieren met letters aangegeven.$$, 'inline'),
  ('4aff9ae1-0c3b-4b84-a49e-5ba3663af1cf', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$hoge bovendruk in het hoofd; Cathy verliest tijdelijk een deel van haar gezichtsvermogen$$,
   $$biologie-havo-2019-i-bungeejumpen-context4.png$$,
   $$Tijdens een bungeejump neemt de bloeddruk toe, vooral in het hoofd. Op het moment dat het laagste punt wordt bereikt, is de bovendruk (systolische druk) in het hoofd enorm hoog. Als gevolg hiervan kunnen haarvaatjes beschadigd raken. Het Engelse meisje Cathy verloor hierdoor tijdelijk een gedeelte van haar gezichtsvermogen.$$, 'inline'),
  ('61759c51-bbcf-4cba-ad63-aa4d336b5473', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$verdeling van de bovendruk bij staande houding$$,
   $$biologie-havo-2019-i-bungeejumpen-context5.png$$,
   $$In afbeelding 3 is de verdeling van de bovendruk weergegeven bij een staande houding.$$, 'inline'),
  ('34e1a4f4-34ad-4a61-a928-e6dd05737147', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$afbeelding 3: bovendruk in hoofd, hart en voeten$$,
   $$biologie-havo-2019-i-bungeejumpen-context6.png$$,
   $$afbeelding 3
bovendruk hoofd 80 mmHg
bovendruk hart 120 mmHg
bovendruk voeten 190 mmHg$$, 'inline'),
  ('be7a4ce6-605f-4b97-8c2c-fabc37dffb5f', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$twee uitspraken over de oorzaak van de hoge bovendruk in het hoofd$$,
   $$biologie-havo-2019-i-bungeejumpen-context7.png$$,
   $$Over de oorzaak van de hoge bovendruk in het hoofd op het laagste punt van de sprong, worden twee uitspraken gedaan:
1 Afgifte van adrenaline leidt tot een verhoging van de bovendruk.
2 De houding van het lichaam draagt bij aan de hoge bovendruk in het hoofd.$$, 'inline'),
  ('b616f670-4f72-4ca8-9c1e-5d8877f42862', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$schade aan het netvlies in gebied M (afbeelding 4)$$,
   $$biologie-havo-2019-i-bungeejumpen-context8.png$$,
   $$De schade aan afbeelding 4 haarvaatjes trad op in een gedeelte van Cathy’s netvlies. Hierdoor werkten de zintuigcellen in het gebied M (aangegeven met de cirkel in afbeelding 4) tijdelijk niet.$$, 'inline'),
  ('d26845cc-b338-42df-aee4-bc58b8e2183b', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$onderzoek naar invloed van stress op het immuunsysteem; vier bloedafnames$$,
   $$biologie-havo-2019-i-bungeejumpen-context9.png$$,
   $$Het opwekken van stress door bungeejumpen wordt door artsen van het Academisch Medisch Centrum gebruikt om de invloed van stress op het immuunsysteem te onderzoeken. Bekend is dat mensen die gestrest zijn sneller last hebben van infecties en eerder ziek worden. Voor dit onderzoek maakten 20 vrijwilligers een bungeejump vanaf
70 meter hoogte. Bij de proefpersonen werd op vier tijdstippen bloed afgenomen:
1 bij aankomst op het terrein
2 vlak voor de sprong, op het springplatform (ongeveer 2 uur na aankomst)
3 direct na de sprong
4 twee uur na de sprong In het bloed werd de hoeveelheid bloedcellen die betrokken zijn bij de afweer geteld en werd de ontstekingsremmende activiteit van de afweercellen bepaald. Een aantal proefpersonen kreeg voorafgaand aan de eerste bloedafname een behandeling die de werking van adrenaline remt.$$, 'inline'),
  ('30c367d5-43f7-48cc-9700-71ba11ad784b', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$vaste bloedbestanddelen genummerd in een microscopisch preparaat$$,
   $$biologie-havo-2019-i-bungeejumpen-context10.png$$,
   $$In afbeelding 5 zijn met nummers verschillende vaste bloedbestanddelen aangeven in een microscopisch preparaat van bloed.$$, 'inline'),
  ('f7dd4d9b-3464-4b3f-adef-3c6fb7075334', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$afbeelding 5: microscopisch preparaat van bloed met nummers 1, 2 en 3$$,
   $$biologie-havo-2019-i-bungeejumpen-context11.png$$,
   $$afbeelding 5: microscopisch preparaat van bloed; drie vaste bloedbestanddelen zijn aangegeven met de nummers 1, 2 en 3$$, 'inline'),
  ('7352b809-91f5-445d-b26c-3161c0bb00e3', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$de resultaten van het onderzoek$$,
   $$biologie-havo-2019-i-bungeejumpen-context12.png$$,
   $$De resultaten uit het onderzoek zijn weergegeven in afbeelding 6.$$, 'inline'),
  ('a6467a37-8e4e-45db-a44d-2bf138fe5bb1', 'e1d2944f-cd26-4d49-987c-9397f9dc5d61', $$afbeelding 6: aantal afweercellen en ontstekingsremmende activiteit per tijdstip$$,
   $$biologie-havo-2019-i-bungeejumpen-context13.png$$,
   $$afbeelding 6 afweercellen per ml bloed
1a 1b 2a 2b 3a 3b 4a 4b
activiteit van de afweercellen ontstekings- remmende
1a 1b 2a 2b 3a 3b 4a 4b Legenda:
1 bij binnenkomst a onbehandeld
2 vlak voor de sprong b met adrenaline-
3 vlak na de sprong remmer
4 twee uur na de sprong$$, 'inline'),
  ('6630b0fd-c4c5-41d9-aeb4-6ee03a16702c', '5821907e-c97a-419a-8029-fd8462cc147f', $$inleiding: vlieëbos met kleverige haren die insecten vangen$$,
   $$biologie-havo-2019-i-planten-die-vliegen-vangen-context1.png$$,
   $$De vlieëbos is een struikachtige plant die groeit in Zuid-Afrika. De bladeren van deze plant zijn begroeid met kleverige haren waaraan kleine insecten blijven kleven. Wetenschappers onderzochten wat het voordeel hiervan is voor de plant.$$, 'inline'),
  ('f2b34fab-26be-4b19-8cea-1e679ee076b6', '5821907e-c97a-419a-8029-fd8462cc147f', $$vleesetende luizen en spinnen op vlieëbos; experiment met gelabelde stikstof (afbeelding 1 en 2)$$,
   $$biologie-havo-2019-i-planten-die-vliegen-vangen-context2.png$$,
   $$Op vlieëbosplanten (Roridula gorgonias, afbeelding 1) leven vleesetende luizen (Pameridea roridulae) die zich op hun hoge poten moeiteloos tussen de kleverige haren van de plant verplaatsen. Ze voeden zich met de door de plant gevangen insecten zoals fruitvliegjes (afbeelding 2). De vleesetende luizen worden gegeten door de spin Synaema marlothii, die zich ook voedt met door de plant gevangen insecten.
afbeelding 1: foto van vlieëbos
afbeelding 2: foto van een vleesetende luis op een kleverige haar
Net als vleesetende planten groeit vlieëbos op vochtige, voedselarme bodems en vangt insecten. In tegenstelling tot vleesetende planten maakt vlieëbos geen enzymen om de insecten te verteren. Onderzoekers vroegen zich af welk voordeel de planten dan hebben van de energie die zij investeren in de afscheiding van de kleverige stof. Om dit te onderzoeken zetten ze een experiment op waarin ze fruitvliegjes voedsel gaven dat gelabelde organische stikstofverbindingen (met zwaar stikstof, ¹⁵N) bevat. De vliegjes werden vervolgens vastgeplakt op de planten met vleesetende luizen. Gelabelde stikstof werd later aangetroffen in de weefsels van deze planten. Het bleek dat stikstof via de uitscheidingsproducten van de vleesetende luizen in de planten terechtkomt.$$, 'inline'),
  ('e31cbf9f-8ced-43d9-aff2-9d67c4917217', '5821907e-c97a-419a-8029-fd8462cc147f', $$luizen breken organische stikstofverbindingen af; stikstof in aminozuren en eiwitten$$,
   $$biologie-havo-2019-i-planten-die-vliegen-vangen-context3.png$$,
   $$Vleesetende luizen breken organische stikstofverbindingen van fruitvliegen af in hun verteringsstelsel. Stikstof komt onder andere voor in aminozuren en eiwitten.$$, 'inline'),
  ('9a0709d3-f7ba-4e75-8c17-4a01235a9ce2', '5821907e-c97a-419a-8029-fd8462cc147f', $$gelabelde stikstof in eiwitten van fruitvliegjes, luizen, spinnen en planten$$,
   $$biologie-havo-2019-i-planten-die-vliegen-vangen-context4.png$$,
   $$De onderzoekers bepaalden aan het eind van het experiment of eiwitten in cellen van fruitvliegjes, luizen, spinnen en planten, de gelabelde stikstof bevatten.$$, 'inline'),
  ('b92d8aa5-c7a3-4928-bda4-cba7f36d27f2', '5821907e-c97a-419a-8029-fd8462cc147f', $$drie uitspraken over de relaties tussen plant, luis, spin en fruitvliegjes$$,
   $$biologie-havo-2019-i-planten-die-vliegen-vangen-context5.png$$,
   $$Over de relaties tussen de plant, de vleesetende luis, de spin en de fruitvliegjes worden drie uitspraken gedaan:
1 Tussen de vleesetende luis en de plant is sprake van mutualisme.
2 Tussen de vleesetende luis en de fruitvliegjes is sprake van parasitisme.
3 Tussen de spin en de fruitvliegjes is sprake van predatie.$$, 'inline'),
  ('1f7b2939-ace7-43a1-a345-a75177845004', '5821907e-c97a-419a-8029-fd8462cc147f', $$vlieëbos groeit op voedselarme bodem door de relatie met de luis$$,
   $$biologie-havo-2019-i-planten-die-vliegen-vangen-context6.png$$,
   $$Door de relatie met de vleesetende luis kan vlieëbos op voedselarme bodem groeien.$$, 'inline'),
  ('67213a62-b465-4723-8654-4d44116213a5', '5821907e-c97a-419a-8029-fd8462cc147f', $$natuurbranden; waboom overleeft door een dikke schors$$,
   $$biologie-havo-2019-i-planten-die-vliegen-vangen-context7.png$$,
   $$In de gebieden waar de struik vlieëbos voorkomt, ontstaan elke paar jaar natuurbranden. De struik kan deze branden overleven doordat het onderste gedeelte van de stam zich onder de grond bevindt. Andere soorten, zoals de waboom (Protea nitida), overleven doordat ze een dikke schors hebben. Hierdoor kunnen deze soorten na een brand opnieuw uitlopen.$$, 'inline'),
  ('e2fe3ac6-0f22-409c-84f7-34f242253c23', '3f065cc4-427a-478d-b744-8cd36eb461fc', $$inleiding: Marja met één slecht functionerende nier moet dialyseren$$,
   $$biologie-havo-2019-i-nierdonor-bij-leven-context1.png$$,
   $$Marja is geboren met slechts één nier. Eén goede nier is genoeg om het bloed te zuiveren, maar Marja’s nier is tijdens de twintig jaar van haar leven steeds slechter gaan functioneren, waardoor ze nu regelmatig moet dialyseren.$$, 'inline'),
  ('106fd4fa-de99-4f92-ab5d-78736bd9d885', '3f065cc4-427a-478d-b744-8cd36eb461fc', $$niertransplantatie door tweelingbroer Arno; veel bloedcellen mee getransplanteerd$$,
   $$biologie-havo-2019-i-nierdonor-bij-leven-context2.png$$,
   $$Een niertransplantatie zou een oplossing zijn. Marja’s tweelingbroer Arno wil graag een van zijn nieren doneren. Bij het transplanteren van een nier moet met verschillende factoren rekening worden gehouden. De nier is een bloedrijk orgaan, waardoor bij een niertransplantatie veel bloedcellen mee worden getransplanteerd.$$, 'inline'),
  ('ebdfc5ec-c2d1-4685-8f13-249d97d5247a', '3f065cc4-427a-478d-b744-8cd36eb461fc', $$geen klontering toegestaan; Marja heeft bloedgroep B$$,
   $$biologie-havo-2019-i-nierdonor-bij-leven-context3.png$$,
   $$Bij transplantatie mag geen klontering van de bloedcellen van Arno optreden in de bloedbaan van Marja. Marja heeft bloedgroep B.$$, 'inline'),
  ('0b29e60e-27be-49d5-ba58-bb65dcb1f8cf', '3f065cc4-427a-478d-b744-8cd36eb461fc', $$HLA-eiwitten op lichaamscellen, gecodeerd op chromosoom 6$$,
   $$biologie-havo-2019-i-nierdonor-bij-leven-context4.png$$,
   $$Een tweede factor waarmee rekening moet worden gehouden bij een niertransplantatie zijn de HLA-eiwitten die zich op alle lichaamscellen bevinden. Deze eiwitten worden gecodeerd door een set genen op chromosoom 6. In deze genen is heel veel variatie, waardoor de kans klein is dat twee personen dezelfde combinatie van HLA-eiwitten bezitten. Tegen niet-lichaamseigen HLA-eiwitten treden immuunreacties op die tot afstoting van getransplanteerde organen kunnen leiden.$$, 'inline'),
  ('4be74032-b6fe-4795-8b19-dddf6326996f', '3f065cc4-427a-478d-b744-8cd36eb461fc', $$gekoppelde overerving van HLA-genen; afbeelding 1: sets HLA-allelen van Marja en ouders$$,
   $$biologie-havo-2019-i-nierdonor-bij-leven-context5.png$$,
   $$Omdat de verschillende genen voor de HLA-eiwitten heel dicht bij elkaar liggen, kun je stellen dat ze gekoppeld overerven en dat kinderen dus van elke ouder een van de twee sets HLA-genen krijgen. In afbeelding 1 zijn van Marja en haar ouders de chromosomen 6 met verschillende sets allelen voor HLA weergegeven.
afbeelding 1: vader heeft set 1 en set 2, moeder heeft set 3 en set 4, Marja heeft set 1 en set 4$$, 'inline'),
  ('f01c3731-cbcd-4e1b-a0fd-1e50686d63f4', '3f065cc4-427a-478d-b744-8cd36eb461fc', $$antistoffen en bloedcellen van het specifieke afweersysteem bij afstoting$$,
   $$biologie-havo-2019-i-nierdonor-bij-leven-context6.png$$,
   $$Bij de afweerreactie tegen bloedgroepeiwitten spelen antistoffen uit het bloed een rol. Cellen van een donornier met lichaamsvreemde HLA- eiwitten worden aangevallen door bloedcellen van het specifieke afweersysteem.$$, 'inline'),
  ('67037300-cac8-4ec4-a24c-63f8ff4a50e2', '3f065cc4-427a-478d-b744-8cd36eb461fc', $$Arno blijkt een geschikte donor$$,
   $$biologie-havo-2019-i-nierdonor-bij-leven-context7.png$$,
   $$Na onderzoek blijkt Arno een geschikte bloedgroep te hebben. Zijn HLA- eiwitten komen niet geheel overeen met die van Marja, maar de match is voldoende om als donor in aanmerking te komen.$$, 'inline'),
  ('42326898-3bd4-48fe-97d4-08c4ad8b08ee', '3f065cc4-427a-478d-b744-8cd36eb461fc', $$transplantatie met aansluitingen P, Q en R (afbeelding 2)$$,
   $$biologie-havo-2019-i-nierdonor-bij-leven-context8.png$$,
   $$Tijdens een operatie wordt Arno’s rechternier naar de buikholte van Marja getransplanteerd. De chirurg maakt drie aansluitingen (met P, Q en R, afbeelding 2) om de aan- en afvoer van vloeistoffen naar en vanaf de donornier mogelijk te maken. In afbeelding 2 is met pijlen de richting van de vloeistofstromen aangegeven.
afbeelding 2: doorsnede van een nier met de aansluitingen P, Q en R$$, 'inline'),
  ('07454dca-bd78-4403-9c2c-13568c9c6381', 'ee64d3b5-f97a-4871-876b-f53acd3a1c52', $$inleiding: klimaatverandering en de Amerikaanse haas als prooi$$,
   $$biologie-havo-2019-i-toch-het-haasje-door-klimaatverandering-context1.png$$,
   $$Door klimaatverandering verandert de omgeving van de Amerikaanse haas (Lepus americanus, afbeelding 1), waardoor hij mogelijk vaker ten prooi valt aan roofdieren.$$, 'inline'),
  ('3dad98ce-249a-476a-93da-8b60a0674b3c', 'ee64d3b5-f97a-4871-876b-f53acd3a1c52', $$roofdieren, leefwijze en vachtwisseling van de haas (afbeelding 1)$$,
   $$biologie-havo-2019-i-toch-het-haasje-door-klimaatverandering-context2.png$$,
   $$Voor veel roofdieren, waaronder de afbeelding 1 coyote, de vos en de lynx, is de haas een prooi die het hele jaar beschikbaar is, want de haas houdt geen winterslaap. Het gedrag, de bouw en de levenswijze van de haas zijn aangepast om aan deze roofdieren te ontsnappen. Omdat de haas geen hol heeft om in te vluchten, geeft hij de voorkeur aan een gebied met voldoende, lage vegetatie. Hierin vindt de haas beschutting en voedsel. De Amerikaanse haas wisselt twee keer per jaar van vacht. Aan het begin van de winter krijgt de haas witte haren en aan het eind van de winter wisselt hij deze weer om voor een bruine vacht. Hiermee is de haas, omdat hij in gebieden met koude winters leeft, in alle seizoenen goed gecamoufleerd.$$, 'inline'),
  ('a2c11e43-4dc3-41a5-991b-c5c48e7b9359', 'ee64d3b5-f97a-4871-876b-f53acd3a1c52', $$vachtwisseling als evolutionair voordeel door natuurlijke selectie$$,
   $$biologie-havo-2019-i-toch-het-haasje-door-klimaatverandering-context3.png$$,
   $$Het wisselen van de vacht geeft de haas een evolutionair voordeel ten opzichte van prooidieren die het hele jaar dezelfde vachtkleur hebben. Bij het ontstaan van deze eigenschap heeft natuurlijke selectie een rol gespeeld.$$, 'inline'),
  ('bc3567a5-3b13-4c6c-8f36-3964c8dce58d', 'ee64d3b5-f97a-4871-876b-f53acd3a1c52', $$onderzoek naar vachtkleur en sneeuw gedurende drie winters$$,
   $$biologie-havo-2019-i-toch-het-haasje-door-klimaatverandering-context4.png$$,
   $$Door klimaatverandering worden de winterperioden anders. De verwachting is dat de perioden met sneeuw korter worden. Natuurbeheerders vroegen zich af of de populatie Amerikaanse hazen zich kan aanpassen aan de veranderende leefomstandigheden. Ze bestudeerden gedurende drie winters elke week de kleur van de vacht van de hazen en noteerden of er sneeuw in het leefgebied lag. De resultaten zijn weergegeven in afbeelding 2.$$, 'inline'),
  ('cbe6326a-6f10-4ca2-9f4b-3da39944683b', 'ee64d3b5-f97a-4871-876b-f53acd3a1c52', $$afbeelding 2: percentage wit in de hazenvacht en periode met sneeuw in drie winters$$,
   $$biologie-havo-2019-i-toch-het-haasje-door-klimaatverandering-context5.png$$,
   $$afbeelding 2: drie diagrammen (winters 2009/2010, 2010/2011 en 2011/2012) met het percentage wit in de hazenvacht (0-100) per week (week 40 t/m week 20) en de periode dat er sneeuw lag$$, 'inline'),
  ('79f336c3-24a8-4c57-b818-8f47934d730a', 'ee64d3b5-f97a-4871-876b-f53acd3a1c52', $$camouflage-mismatch; twee beweringen$$,
   $$biologie-havo-2019-i-toch-het-haasje-door-klimaatverandering-context6.png$$,
   $$De beheerders vrezen dat er door veranderende winters meer sprake zal zijn van camouflage-mismatch. Met camouflage-mismatch wordt bedoeld dat de kleur van de vacht niet is aangepast aan de omgeving. Twee beweringen zijn:
1 In elk van de drie onderzochte winters komt camouflage mismatch voor.
2 De eerste sneeuwval is de bepalende factor om van vachtkleur te wisselen.$$, 'inline'),
  ('7c4757eb-a7b6-4521-b328-ffa768b1f727', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$inleiding: profielwerkstuk over aquaponics$$,
   $$biologie-havo-2019-i-aquaponics-context1.png$$,
   $$Tijdens het bekijken van een website met suggesties voor profielwerkstukken raken Joey en Tom geïnteresseerd in het onderwerp aquaponics (afbeelding 1).$$, 'inline'),
  ('1e7be7ab-6455-4927-8ac8-e7e38ecc4dfe', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$afbeelding 1: websitetekst over aquaponics als gesloten, duurzaam systeem$$,
   $$biologie-havo-2019-i-aquaponics-context2.png$$,
   $$afbeelding 1
Aquaponics: planten kweken op vissenpoep Een nieuwe duurzame manier om voedsel te produceren!
Met de toenemende wereldbevolking wordt het zoetwaterverbruik steeds groter. Er zal dus met minder water meer voedsel moeten worden geproduceerd.
Aquaponics is een gesloten ecosysteem waarbij planten op kleikorrels worden gekweekt. De voedingsstoffen die de planten gebruiken, komen uit de ontlasting van vissen en het waterverbruik is 80-90% lager dan in de traditionele tuinbouw. Daarmee is aquaponics een duurzame manier van voedselproductie, waarbij zowel groente als vis wordt gekweekt. Alleen visvoer moet worden toegevoegd.$$, 'inline'),
  ('39583d67-25a2-434b-ac0b-8ce621a0b726', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$aquaponics is geen gesloten ecosysteem; water wordt verbruikt$$,
   $$biologie-havo-2019-i-aquaponics-context3.png$$,
   $$Joey en Tom vinden aquaponics geen gesloten ecosysteem omdat niet alle kringlopen van stoffen gesloten zijn. Zo wordt er bijvoorbeeld water verbruikt.$$, 'inline'),
  ('9e119aa5-5e39-4245-81ab-f04b56a55f99', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$schematische weergave van een aquaponics-opstelling; bacteriën in kleikorrels zuiveren water$$,
   $$biologie-havo-2019-i-aquaponics-context4.png$$,
   $$Op de website van de universiteit van Hawaii vindt Tom een schematische weergave van een aquaponics-opstelling (afbeelding 2). Het water waarin de vissen zwemmen, wordt opgepompt en komt, gezuiverd door bacteriën in de kleikorrels, weer terug.$$, 'inline'),
  ('a4631838-861e-4824-b228-31e405422185', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$afbeelding 2: schema aquaponics-opstelling met vistank, houten deksel en kweekbed$$,
   $$biologie-havo-2019-i-aquaponics-context5.png$$,
   $$afbeelding 2: schema van een aquaponics-opstelling: vistank met houten deksel en beluchting (luchtpomp), waterpomp, filter en kweekbed met kleikorrels. Legenda: doorgetrokken lijn = waterstroom, stippellijn = luchtstroom$$, 'inline'),
  ('72e8ffd1-799b-4e95-b36a-afc70d9a27f8', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$door het houten deksel komt geen licht in de vistank$$,
   $$biologie-havo-2019-i-aquaponics-context6.png$$,
   $$Door het houten deksel komt er geen licht in de vistank.$$, 'inline'),
  ('ca0f97ef-e8a7-4b6e-bd24-2acc75989c6c', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$vissen scheiden stikstof uit als ammonium$$,
   $$biologie-havo-2019-i-aquaponics-context7.png$$,
   $$Vissen scheiden stikstof uit in de vorm van ammonium (NH₄⁺). Planten nemen stikstof vooral op in een andere vorm.$$, 'inline'),
  ('a4beec5c-a790-427c-835b-22ad890f6f64', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$tilapia gekweekt met tomaat of met paksoi (afbeelding 3)$$,
   $$biologie-havo-2019-i-aquaponics-context8.png$$,
   $$Aan de universiteit van Hawaii werd in één aquaponics-opstelling tilapia samen met tomaat gekweekt, in een tweede aquaponics-opstelling werd tilapia samen met paksoi gekweekt (afbeelding 3).$$, 'inline'),
  ('de56330d-4489-490f-bfe1-c5d9652ae273', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$afbeelding 3: foto's van tomaat, paksoi en tilapia$$,
   $$biologie-havo-2019-i-aquaponics-context9.png$$,
   $$afbeelding 3
tomaat paksoi
tilapia$$, 'inline'),
  ('f4dc76cf-e77f-414e-be1f-3b01a1d429b2', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$na 135 dagen beëindigd; resultaten in tabel 1$$,
   $$biologie-havo-2019-i-aquaponics-context10.png$$,
   $$Na 135 dagen werd het experiment beëindigd. De resultaten staan weergegeven in tabel 1.$$, 'inline'),
  ('8e5498ef-d175-4533-9ac8-764ee0dd7a3d', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$tabel 1: gewichten vissen, voedselconversiefactor en plantproductie$$,
   $$biologie-havo-2019-i-aquaponics-context11.png$$,
   $$tabel 1
| | gekweekt samen met tomaat | gekweekt samen met paksoi |
| totaal startgewicht vissen (g) | 6138 | 6031 |
| totaal eindgewicht vissen (g) | 10483 | 9317 |
| voedselconversiefactor | 1,6 | 2,0 |
| productie planten (drooggewicht, g) | 3766 | 1077 |
| eetbare deel planten (drooggewicht, g) | 1218 | 1071 |$$, 'inline'),
  ('fd435719-f169-45db-ac45-2effdb77f26d', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$definitie van de voedselconversiefactor$$,
   $$biologie-havo-2019-i-aquaponics-context12.png$$,
   $$De voedselconversiefactor geeft aan hoe efficiënt het voedsel door dieren wordt gebruikt. Deze factor is in dit geval de hoeveelheid visvoer (in gram) die nodig is om één gram tilapia te produceren.$$, 'inline'),
  ('cd09b99e-9453-4e7f-ad69-1f882621d004', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$vissen zetten niet al het voer om in lichaamsgewicht; twee oorzaken$$,
   $$biologie-havo-2019-i-aquaponics-context13.png$$,
   $$De vissen zetten niet al het opgegeten voer om in lichaamsgewicht. Dat heeft twee oorzaken.$$, 'inline'),
  ('02cd9a0e-2481-40ce-ab0d-a66c461cebdd', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$computermodel voor de tilapia-opbrengst$$,
   $$biologie-havo-2019-i-aquaponics-context14.png$$,
   $$Joey en Tom stellen met behulp van de computer een model op om de tilapia-opbrengst van een aquaponics-systeem te bepalen.$$, 'inline'),
  ('60f94e1e-c746-415f-9e34-bffe6a55c9ca', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$afbeelding 4: foto van Joey en Tom aan de computer$$,
   $$biologie-havo-2019-i-aquaponics-context15.png$$,
   $$afbeelding 4: foto van Joey en Tom die met de computer een model opstellen$$, 'inline'),
  ('d8b96240-ce50-4706-8c8d-000f45a58ad2', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$parameters a t/m f van het model$$,
   $$biologie-havo-2019-i-aquaponics-context16.png$$,
   $$In het model geven ze de parameters als volgt weer:
a totaal startgewicht vissen (g)
b totaal eindgewicht vissen (g)
c totaalgewicht voedsel (g)
d voedselconversiefactor
e productie planten (drooggewicht, g)
f eetbare deel planten (drooggewicht, g)$$, 'inline'),
  ('555c60f7-05c6-4ab4-8ef8-537f6b8e02cf', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$formule voor de tilapia-opbrengst invoeren$$,
   $$biologie-havo-2019-i-aquaponics-context17.png$$,
   $$In het model moeten ze een formule invoeren voor de tilapia-opbrengst.$$, 'inline'),
  ('d397c07f-7051-4120-9d76-068c47b17744', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$bewering van Joey: paksoi kweken is gunstiger dan tomaten$$,
   $$biologie-havo-2019-i-aquaponics-context18.png$$,
   $$Joey leidt uit tabel 1 af dat van een tomatenplant maar een klein gedeelte eetbaar is, terwijl van paksoi bijna de gehele plant gegeten wordt. Hij beweert dat het daarom in een aquaponics-systeem gunstiger is om paksoi te kweken dan tomaten.$$, 'inline'),
  ('3cdd9f6f-7dea-4747-8398-f54f586ce1fb', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$stikstofconcentraties in aquaponics vergeleken met aquacultuur$$,
   $$biologie-havo-2019-i-aquaponics-context19.png$$,
   $$Joey en Tom onderzoeken ook de duurzame aspecten van aquaponics. Ze vergelijken hiervoor de concentraties van stikstofverbindingen in het water in de vistank van een aquaponics-systeem met die van een aquacultuursysteem (afbeelding 5). Bij aquacultuursystemen wordt in grote bassins alleen vis gekweekt. De overige omstandigheden komen overeen.$$, 'inline'),
  ('d8aadd45-bf1a-401f-86d5-8c7bb1b9feaa', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$afbeelding 5: concentratie stikstofverbindingen in aquacultuur- en aquaponics-systeem$$,
   $$biologie-havo-2019-i-aquaponics-context20.png$$,
   $$afbeelding 5: staafdiagram van de concentratie stikstofverbindingen (mg N/L, 0-300) in de vistank: aquacultuursysteem hoog (ongeveer 240), aquaponics-systeem laag (ongeveer 20)$$, 'inline'),
  ('4d789858-3924-4383-a7c8-34a0b8f3d773', 'fbeefe32-8f56-4621-8647-6b4c1ba97f69', $$uitspraken van Joey en Tom over stikstof en duurzaamheid$$,
   $$biologie-havo-2019-i-aquaponics-context21.png$$,
   $$Joey en Tom doen elk een uitspraak over de duurzaamheid van aquaponics-systemen in vergelijking met aquacultuursystemen. Joey: “Bij aquaponics moet met het visvoer meer stikstof (N) worden toegevoegd om evenveel vis te kunnen oogsten.” Tom: “Bij aquaponics wordt een groter deel van de hoeveelheid stikstof (N) uit het visvoer benut voor de menselijke voedselproductie.”$$, 'inline'),
  ('5eb91728-da80-4c1c-951d-b2468660bbbd', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$inleiding: Lorenzo doneert bloedplasma$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context1.png$$,
   $$Carla is verpleegkundige bij een bloedafnamepost. Ze prikt een ader aan bij Lorenzo, die bloedplasma gaat doneren.$$, 'inline'),
  ('13df32d3-b955-4cd1-a259-bdfffcd1ea58', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$plasmaferese-machine scheidt plasma van bloedcellen (afbeelding 1)$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context2.png$$,
   $$Lorenzo’s bloed stroomt via een slangetje naar een plasmaferese-machine, waarin het bloedplasma wordt gescheiden van de vaste bloedbestanddelen. De plasmaferese-machine slaat het plasma op in een plasmazak (afbeelding 1). Lorenzo krijgt zijn eigen bloedcellen weer terug in een vervangende kunstmatige oplossing. Dit gaat via hetzelfde slangetje en dezelfde naald.
afbeelding 1: foto van een plasmadonatie met plasmaferese-machine$$, 'inline'),
  ('704f2f82-d294-4962-aecb-94b1ddcfcc66', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$knijpen in een balletje; twee uitspraken over de bloedstroom$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context3.png$$,
   $$Carla adviseert Lorenzo afwisselend in een balletje te knijpen en te ontspannen. Hierdoor kan de afname sneller verlopen, omdat de bloedstroom uit de hand naar de aders gestimuleerd wordt. Hierover worden twee uitspraken gedaan:
1 Door het knijpen en loslaten wordt de dissimilatie in de spieren in de hand en onderarm gestimuleerd, waardoor meer bloed wordt aangevoerd.
2 Door het knijpen neemt de druk in de aders in de hand en onderarm toe, waardoor het bloed sneller wordt afgevoerd.$$, 'inline'),
  ('4906266f-cdc2-4ef1-a2b9-bad65fd1fbf4', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$bloedcellen teruggegeven in fysiologische zoutoplossing$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context4.png$$,
   $$Lorenzo ontvangt zijn eigen bloedcellen terug in een kunstmatige oplossing (fysiologische zoutoplossing).$$, 'inline'),
  ('f58f7f58-4077-4317-afb3-0ca7c9791db5', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$volbloeddonatie versus plasmadonatie; hoe vaak doneren is toegestaan$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context5.png$$,
   $$Vorig jaar was Lorenzo volbloeddonor. Bij volbloeddonatie worden alle bloedbestanddelen gedoneerd. Bij plasmadonatie en bij volbloeddonatie wordt per keer ongeveer een halve liter afgestaan. Plasma doneren mag één keer per twee weken, donatie van volbloed slechts drie tot vijf keer per jaar. Lorenzo vraagt aan Carla waarom hij nu vaker mag doneren.$$, 'inline'),
  ('8e5b1e74-94f7-4096-ab6e-1b7612f020af', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$HSA, het meest voorkomende eiwit in bloedplasma$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context6.png$$,
   $$Uit bloedplasma worden eiwitten gewonnen. Het meest voorkomende eiwit in bloedplasma is HSA (Humaan Serum Albumine). Dit HSA wordt toegediend aan patiënten met brandwonden of zeer groot bloedverlies.$$, 'inline'),
  ('7c17f7c5-c1f5-434a-98fb-83afedd7d2e7', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$vier functies van eiwitten in het bloed$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context7.png$$,
   $$Enkele functies van verschillende typen eiwitten in het bloed zijn:
1 zuurstoftransport
2 (terug)resorptie van weefselvocht
3 antistof
4 hormoon$$, 'inline'),
  ('6ac48002-41b8-4f77-8c4e-c8e8e03be40d', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$genetisch gemodificeerde rijst, bacteriën en gisten produceren HSA; vorming van HSA in levercellen$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context8.png$$,
   $$In Azië is een rijstras genetisch gemodificeerd zodat het grote hoeveelheden HSA kan produceren. Eerder werden bacteriën en gisten al gemodificeerd, zodat ze HSA gingen produceren. Echter, HSA van de bacteriën was niet werkzaam en HSA uit de gistcellen bleek moeilijk te zuiveren. De productie en verwerking van HSA uit rijstzaden is makkelijker en goedkoper. In menselijke levercellen wordt HSA gemaakt op basis van de informatie van een gen. Het eiwit wordt gevormd door de ribosomen, waarna het in het endoplasmatisch reticulum en het golgi-systeem wordt gevouwen en getransporteerd naar buiten de cel.$$, 'inline'),
  ('f0dbde2a-cafb-4782-a704-b6138286e20c', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$productie van HSA met het menselijk gen$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context9.png$$,
   $$Voor de productie van HSA maken bacteriën, gistcellen en rijstplanten gebruik van het menselijk gen.$$, 'inline'),
  ('cd4670c8-a9c2-4999-b6fc-11f990af98a1', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$genetische modificatie van rijst met behulp van Agrobacterium$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context10.png$$,
   $$Bij de genetische modificatie van de rijstplanten is gebruikgemaakt van een bacterie (Agrobacterium tumefaciens). De bacterie wordt gebruikt om een menselijk gen over te dragen naar een plant, in dit geval de rijstplanten.$$, 'inline'),
  ('e000d100-41d2-4bcf-b0ac-43f9e56eed35', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$GM-HSA bij levercirrose bij ratten$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context11.png$$,
   $$HSA wordt ook bij de behandeling van patiënten met levercirrose gebruikt. Levercirrose is een ernstige aantasting van de lever. Bij ratten met levercirrose bleek een behandeling met HSA uit rijst (GM-HSA) net zo succesvol als een behandeling met HSA uit menselijk donorbloed.$$, 'inline'),
  ('96d58095-dff9-47ba-bc63-684a1b81aa09', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$onderzoek met 36 patiënten met levercirrose in groepen met verschillend infuus$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context12.png$$,
   $$Onderzoekers willen nu weten wat het effect is van de behandeling van mensen met levercirrose met GM-HSA. Ook zijn ze benieuwd of dit effect overeenkomt met dat van een behandeling met HSA uit donorbloed. Om beide vragen te onderzoeken, hebben de onderzoekers 36 patiënten met levercirrose geselecteerd. Deze patiënten hebben een overeenkomstig ziektebeeld en krijgen dezelfde medische verzorging. De patiënten werden ingedeeld in groepen die een verschillend infuus toegediend kregen.$$, 'inline'),
  ('c10f3f22-eb31-426f-ac51-11243ae914d6', '4269ac33-5a9e-4a65-af87-f8780e77aae3', $$aanvraag veldproeven; plasmadonoren blijven nodig$$,
   $$biologie-havo-2019-i-rijst-doneert-menselijk-bloedeiwit-context13.png$$,
   $$Voor het uitvoeren van veldproeven met de gemodificeerde rijstrassen schrijven de onderzoekers een aanvraag om toestemming te krijgen. Hierin geven ze argumenten voor het gebruik van GM-HSA. Een van deze argumenten is dat door de ontwikkeling van GM-HSA veel minder plasmadonoren nodig zullen zijn. Toch zullen er, als GM-HSA succesvol ingezet gaat worden, nog steeds plasmadonoren nodig blijven.$$, 'inline'),
  ('2d0dc861-186b-4f1a-887b-e2a61f17cca6', '8cd065ae-0434-43f4-9939-76f9b41aa2fb', $$inleiding: smeerwortel op een wondje; allantoïne, choline en PA's (afbeelding 1)$$,
   $$biologie-havo-2019-i-smeerwortel-context1.png$$,
   $$Als Adella zich in haar vinger snijdt bij het schillen van een appel, legt haar oma er een paar gekneusde bladeren van de smeerwortel op. Volgens oma helpt dit om de wond sneller te laten genezen. Adella wil weten of dit echt zo is.
Adella leest dat smeerwortel (Symphytum officinale, afbeelding 1) allantoïne bevat, een stof die de celdeling stimuleert. Ook bevat smeerwortel choline, dat nodig is voor de synthese van bepaalde neurotransmitters. De plant produceert daarnaast pyrrolizidine alkaloïden (PA’s). Deze giftige stoffen worden in verband gebracht met leveraandoeningen bij de mens.
afbeelding 1: tekening van de smeerwortel$$, 'inline'),
  ('c7d4c762-9753-46b9-97af-3433a1068dde', '8cd065ae-0434-43f4-9939-76f9b41aa2fb', $$smeerwortel kan genezing van wondjes stimuleren$$,
   $$biologie-havo-2019-i-smeerwortel-context2.png$$,
   $$Enkele onderzoeken geven aan dat het gebruik van smeerwortel genezing van wondjes kan stimuleren.$$, 'inline'),
  ('be7bad4f-a13f-47f8-ac5d-2ecc155aa9ba', '8cd065ae-0434-43f4-9939-76f9b41aa2fb', $$PA's leveren de smeerwortel een evolutionair voordeel op$$,
   $$biologie-havo-2019-i-smeerwortel-context3.png$$,
   $$Het produceren van PA’s levert de smeerwortel een evolutionair voordeel op.$$, 'inline'),
  ('de6ec014-9f40-438e-a7c8-58ba137c221e', '8cd065ae-0434-43f4-9939-76f9b41aa2fb', $$inname van smeerwortel en leveraandoeningen; thee wordt afgeraden$$,
   $$biologie-havo-2019-i-smeerwortel-context4.png$$,
   $$Amerikaans onderzoek toonde een oorzakelijk verband aan tussen inname van grote hoeveelheden smeerwortel en het ontstaan van leveraandoeningen. Het drinken van thee van de blaadjes van smeerwortel wordt daarom sterk afgeraden. Voor wondbehandeling met smeerwortel geldt geen negatief advies.$$, 'inline'),
  ('01754f7b-63ea-4de8-b4f2-f56194eef49d', '8cd065ae-0434-43f4-9939-76f9b41aa2fb', $$chromosoomtypen 24, 40 en 48; kruisingsonderzoek$$,
   $$biologie-havo-2019-i-smeerwortel-context5.png$$,
   $$Er blijken verschillende variëteiten (chromosoomtypen) van de smeerwortel te zijn, elk met een verschillend chromosoomaantal. Zo zijn er smeerwortels met 24, 40 of 48 chromosomen per cel. Bij een onderzoek zijn grote aantallen smeerwortels van verschillende variëteiten met elkaar gekruist. De onderzoekers hoopten hiermee een antwoord te kunnen geven op de vraag of de smeerwortelvariëteiten in Nederland tot één soort behoren. De onderzoekers bestoven de bloemen handmatig door met een kwastje stuifmeel over te brengen van de ene naar de andere bloem. Zo werden bijvoorbeeld bloemen van planten met chromosoomtype 24 bestoven met stuifmeel van planten met chromosoomtype 40.$$, 'inline'),
  ('c4f1cc68-8dab-408a-af9e-d41250a2331d', '8cd065ae-0434-43f4-9939-76f9b41aa2fb', $$castreren van moederbloemen om zelfbestuiving te voorkomen$$,
   $$biologie-havo-2019-i-smeerwortel-context6.png$$,
   $$Voor het handmatig bestuiven zijn in een vroegtijdig stadium de bloemen van de moederplant gecastreerd door de meeldraden te verwijderen. Hierdoor wordt voorkomen dat zelfbestuiving plaatsvindt.$$, 'inline'),
  ('c6d55840-46ec-456e-a88c-bd0fe38942a3', '8cd065ae-0434-43f4-9939-76f9b41aa2fb', $$de resultaten staan in tabel 1$$,
   $$biologie-havo-2019-i-smeerwortel-context7.png$$,
   $$De resultaten van het onderzoek staan in tabel 1.$$, 'inline'),
  ('13804dfa-231d-410e-af0f-6268f3ac621d', '8cd065ae-0434-43f4-9939-76f9b41aa2fb', $$tabel 1: kruisingen van chromosoomtypen en nakomelingen$$,
   $$biologie-havo-2019-i-smeerwortel-context8.png$$,
   $$tabel 1
| chromosoomtype moederplanten | chromosoomtype vaderplanten | aantal nakomelingen | chromosoomtype nakomeling |
| 24 | 40 | 0 | |
| 24 | 48 | 1 | 36 |
| 40 | 24 | 0 | |
| 40 | 48 | 8 | 44 |
| 48 | 40 | 32 | 44 |$$, 'inline'),
  ('29eb59cf-9970-4daf-a06c-ce65944ded13', '8cd065ae-0434-43f4-9939-76f9b41aa2fb', $$twee uitspraken over de smeerwortelvariëteiten$$,
   $$biologie-havo-2019-i-smeerwortel-context9.png$$,
   $$Over de smeerwortelvariëteiten worden twee uitspraken gedaan:
1 Chromosoomtype 24 en chromosoomtype 40 behoren tot dezelfde soort.
2 Van de chromosoomtypen in Nederland zijn chromosoomtype 24 en chromosoomtype 48 het meest verwant aan elkaar.$$, 'inline'),
  ('765317de-57c4-46e3-8448-94727be2152c', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$inleiding: MERS, een ernstige longontsteking door een onbekend virus$$,
   $$biologie-havo-2019-i-mers-context1.png$$,
   $$In 2012 werd in het Midden-Oosten bij verschillende patiënten een zeer ernstige longontsteking geconstateerd die veroorzaakt werd door een tot dan toe onbekend virus. In meer dan 30 procent van de ziektegevallen overleed de patiënt. Het was dus belangrijk om de ziekteverwekker en de bron van de infectie te bepalen. De ziekte kreeg de naam MERS (Middle East Respiratory Syndrome).$$, 'inline'),
  ('e2f1e71c-96aa-4120-99f4-ccc30f7588a4', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$ontstekingsreactie: vocht en afweercellen in de longblaasjes belemmeren de gaswisseling$$,
   $$biologie-havo-2019-i-mers-context2.png$$,
   $$De virusinfectie leidt tot een heftige ontstekingsreactie in de longen, waarbij vocht, eiwitten en afweercellen uit de haarvaatjes in de longblaasjes terechtkomen. Hierdoor wordt de gaswisseling ernstig belemmerd en ontstaat zuurstoftekort.$$, 'inline'),
  ('6769b02e-6307-4c6e-8c3c-70a87d5127c1', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$hoestbuien door samentrekkende ademhalingsspieren$$,
   $$biologie-havo-2019-i-mers-context3.png$$,
   $$Mensen met MERS hebben heftige hoestbuien. Doordat bepaalde ademhalingsspieren samentrekken wordt er lucht en vocht uit de longen verwijderd.$$, 'inline'),
  ('432530d9-4cb1-4d41-8e5e-c0a51e1b66a0', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$coronavirus met RNA; afbeelding 1: vermeerdering van het virus (P, Q, R, S)$$,
   $$biologie-havo-2019-i-mers-context4.png$$,
   $$In het Erasmus Medisch Centrum in Rotterdam werd de ziekteverwekker geïdentificeerd: het bleek een coronavirus met RNA als drager van de erfelijke informatie. De ontdekkers van het virus vermoedden dat het ging om een gemuteerd virus afkomstig uit vee. In afbeelding 1 is de vermeerdering van het virus vereenvoudigd weergegeven.
afbeelding 1: schema van de vermeerdering van het virus in een cel: P = virus-RNA komt de cel binnen; Q = aanmaken van erfelijk materiaal voor volgende generatie virussen; R = aanmaken van viruseiwitten; S = volgende generatie virussen verlaat de cel$$, 'inline'),
  ('54d46be9-6b64-4ec5-a5c2-85cc15901557', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$virus-RNA voor viruseiwitten en nieuw RNA; verpakking via ER en golgi-systeem$$,
   $$biologie-havo-2019-i-mers-context5.png$$,
   $$Na infectie door het virus wordt het virus-RNA gebruikt om virus-eiwitten te maken. Ook wordt het RNA gebruikt om nieuwe virus-RNA-moleculen te maken. In het endoplasmatisch reticulum worden deze RNA-moleculen in de viruseiwitten verpakt waardoor nieuwe virussen ontstaan. Via het golgi-systeem worden de nieuwe virussen getransporteerd naar buiten de cel.$$, 'inline'),
  ('aab0926c-7d78-4ff3-8589-1c15c8eabbe5', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$drie rollen van het virus-RNA vergeleken met menselijk RNA$$,
   $$biologie-havo-2019-i-mers-context6.png$$,
   $$Drie rollen van het virus-RNA zijn:
1 basis voor de synthese van RNA
2 doorgeven van erfelijke informatie aan de volgende generatie
3 informatie leveren voor de eiwitsynthese Deze rollen worden vergeleken met de functie van menselijk RNA in een niet-geïnfecteerde menselijke cel.$$, 'inline'),
  ('d2a92241-3226-40ce-bb5b-98bf397ea765', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$veranderingen in het virus bij de processen Q en R$$,
   $$biologie-havo-2019-i-mers-context7.png$$,
   $$Het lijkt erop dat in de afgelopen jaren veranderingen in het virus zijn opgetreden waardoor het nu ook menselijke cellen kan infecteren. In afbeelding 1 zijn de processen Q en R aangegeven.$$, 'inline'),
  ('82237c06-646e-460d-8a43-0458cbc525ba', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$bron van infectie: 74% van de dromedarissen in aanraking met het virus$$,
   $$biologie-havo-2019-i-mers-context8.png$$,
   $$Toen de ziekteverwekker bekend was, kon de bron van infectie worden opgespoord. Hiervoor werd bloed van een groot aantal schapen, geiten en dromedarissen onderzocht. Van de dromedarissen bleek 74% met het virus in aanraking te zijn geweest.$$, 'inline'),
  ('f3d85324-37e0-4d79-8770-3dbb83af6552', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$dromedarissen zijn immuun geworden voor het virus$$,
   $$biologie-havo-2019-i-mers-context9.png$$,
   $$Hoewel bij deze dromedarissen het virus zelf niet altijd aan te tonen was, kon worden aangetoond dat de dieren immuun waren geworden voor het virus en dus ermee besmet moeten zijn geweest.$$, 'inline'),
  ('ee92b3db-5e30-4b0c-ac32-1bd91f5336fb', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$test met viruseiwitten en serum in een petrischaal met gelei$$,
   $$biologie-havo-2019-i-mers-context10.png$$,
   $$Om vast te stellen of een dromedaris besmet is geweest, gebruikt een medisch laborant een petrischaal met een gelei-laag. In een kuiltje in de gelei pipetteert hij een mengsel van viruseiwitten. In een ander kuiltje brengt hij serum (bloedplasma zonder stollingseiwitten) van een dromedaris aan (afbeelding 2a). Als het dier met het virus in aanraking is geweest, dan ontstaat na verloop van tijd een neerslag tussen de twee kuiltjes omdat stoffen uit het serum en het eiwitmengsel met elkaar reageren (afbeelding 2b).$$, 'inline'),
  ('865922c9-ae46-43dc-89e3-fcd223f01c71', '7994c7e7-8ce6-43d3-a896-b6a93f9d88ba', $$afbeelding 2: kuiltjes met viruseiwitten en serum (a) en neerslag (b)$$,
   $$biologie-havo-2019-i-mers-context11.png$$,
   $$afbeelding 2: (a) petrischaal met een kuiltje met viruseiwitten en een kuiltje met serum; (b) neerslag tussen de twee kuiltjes$$, 'inline');

